import{_ as a,o,c as i,a3 as t}from"./chunks/framework.B9qR_F1m.js";const m=JSON.parse('{"title":"Checking your files: validate and schema","description":"","frontmatter":{},"headers":[],"relativePath":"validate.md","filePath":"validate.md"}'),r={name:"validate.md"};function s(d,e,c,n,l,h){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="checking-your-files-validate-and-schema" tabindex="-1">Checking your files: <code>validate</code> and <code>schema</code> <a class="header-anchor" href="#checking-your-files-validate-and-schema" aria-label="Permalink to &quot;Checking your files: `validate` and `schema`&quot;">​</a></h1><h2 id="ripeat-validate-file" tabindex="-1"><code>ripeat validate [file ...]</code> <a class="header-anchor" href="#ripeat-validate-file" aria-label="Permalink to &quot;`ripeat validate [file ...]`&quot;">​</a></h2><p>Checks ripeat&#39;s input files and reports <strong>every</strong> problem in one go, before anything is installed. Nothing is read from or written to the machine&#39;s state.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ripeat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    # ./ripeat.yaml, ./ripeat.policy.yaml, ./ripeat.lock, your recipes</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ripeat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-recipe.yaml</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # just this file</span></span></code></pre></div><p>The kind of file is recognised from its content: <code>*.lock</code> is a lockfile, otherwise <code>platforms:</code> means a recipe, <code>tools:</code> a profile, <code>groups:</code> or <code>users:</code> an account policy, and keys such as <code>allow_methods:</code> or <code>deny_tools:</code> an administrator policy. Any other file is an error. With no arguments, the files above are checked if they exist, the system administrator policy (<a href="./admin-policy">Administrator policy</a>) if there is one, every saved profile (<a href="./profiles">Profiles: your list</a>), plus every <code>*.yaml</code> in <code>$RIPEAT_HOME/recipes/</code>.</p><p>Each file gets one line: <code>✓</code> valid, <code>!</code> valid with warnings, <code>✗</code> has errors, with each problem under it as <code>error: ...</code> or <code>warning: ...</code>. Errors would make ripeat fail, and the command then exits with an error. Warnings work but are probably not what you meant. With no errors it ends with <code>All N files valid.</code> (<code>, with M warnings</code> when there are some). Marks are coloured on a terminal only; <code>NO_COLOR</code> turns the colour off.</p><h3 id="errors-in-every-file-kind" tabindex="-1">Errors in every file kind <a class="header-anchor" href="#errors-in-every-file-kind" aria-label="Permalink to &quot;Errors in every file kind&quot;">​</a></h3><p>Unknown keys (a typo such as <code>pakage:</code> or <code>tool:</code>) and invalid YAML.</p><h3 id="recipes-recipes" tabindex="-1">Recipes (<a href="./recipes">Recipes</a>) <a class="header-anchor" href="#recipes-recipes" aria-label="Permalink to &quot;Recipes ([Recipes](./recipes))&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Error</th><th>Warning</th></tr></thead><tbody><tr><td>name not lowercase letters, digits, <code>.</code> <code>_</code> <code>-</code></td><td>no <code>check</code> (ripeat cannot tell if the tool is already there)</td></tr><tr><td>no <code>platforms</code>, a platform other than <code>linux</code>/<code>windows</code>/<code>darwin</code>, a platform with no options</td><td><code>shell</code> without <code>uninstall</code> (cannot be uninstalled or rolled back)</td></tr><tr><td>unknown install method</td><td><code>deb_url</code> (not checksum-verified)</td></tr><tr><td>a key the method requires is missing (<code>package</code>; <code>url</code>, <code>install</code>, <code>repo</code>, <code>asset</code>, <code>bins</code>, <code>sha256</code> per method)</td><td>a URL using plain <code>http</code></td></tr><tr><td><code>scope</code> other than <code>user</code> or <code>system</code>; <code>source</code> other than <code>winget</code> or <code>msstore</code></td><td>a key the method does not use</td></tr><tr><td><code>requires</code> a tool that has no recipe, or a dependency cycle</td><td><code>github_release</code> without <code>checksum_asset</code></td></tr><tr><td><code>repo</code> not <code>owner/name</code>; <code>asset</code> not a valid regular expression; unknown <code>{placeholder}</code>; <code>sha256</code> not 64 hex characters</td><td></td></tr><tr><td><code>product</code> that is blank, longer than 80 characters or on several lines</td><td><code>product</code> on a dmg (it is only read on Windows)</td></tr><tr><td><code>package</code> of a package-manager method that is not plain package names (letters, digits and <code>. _ + @ : / -</code>, never starting with <code>-</code>): the names become arguments of the package manager, and <code>-o ...</code> after one would be read as an option</td><td></td></tr></tbody></table><h3 id="profiles-profiles-your-list" tabindex="-1">Profiles (<a href="./profiles">Profiles: your list</a>) <a class="header-anchor" href="#profiles-profiles-your-list" aria-label="Permalink to &quot;Profiles ([Profiles: your list](./profiles))&quot;">​</a></h3><p>Wrong <code>version</code>, empty list, and any tool that has no recipe.</p><h3 id="policies-users-and-groups" tabindex="-1">Policies (<a href="./policy">Users and groups</a>) <a class="header-anchor" href="#policies-users-and-groups" aria-label="Permalink to &quot;Policies ([Users and groups](./policy))&quot;">​</a></h3><p>Unsafe or invalid names, duplicate users, a shell that is not an absolute path, an empty policy.</p><h3 id="administrator-policies-administrator-policy" tabindex="-1">Administrator policies (<a href="./admin-policy">Administrator policy</a>) <a class="header-anchor" href="#administrator-policies-administrator-policy" aria-label="Permalink to &quot;Administrator policies ([Administrator policy](./admin-policy))&quot;">​</a></h3><p>Unknown keys, a version other than <code>1</code>, an unknown install method, a malformed domain, and a method that is both allowed and denied. A tool name with no recipe is a warning. For the system policy file, <code>validate</code> also reports what ripeat itself would refuse: a file not owned by root or writable by others.</p><h3 id="lockfiles-the-lockfile" tabindex="-1">Lockfiles (<a href="./lockfile">The lockfile</a>) <a class="header-anchor" href="#lockfiles-the-lockfile" aria-label="Permalink to &quot;Lockfiles ([The lockfile](./lockfile))&quot;">​</a></h3><p>Unknown method, a malformed platform key (not like <code>linux/amd64</code>), a <code>sha256</code> that is not 64 hex characters. A pin for a tool with no recipe is a warning.</p><h2 id="what-it-does-not-check" tabindex="-1">What it does not check <a class="header-anchor" href="#what-it-does-not-check" aria-label="Permalink to &quot;What it does not check&quot;">​</a></h2><p><code>ripeat validate</code> with no arguments checks your own files: <code>ripeat.yaml</code>, <code>ripeat.policy.yaml</code>, <code>ripeat.lock</code>, your recipes, your saved profiles and the administrator policy. It does <strong>not</strong> check the recipes of added packs (<a href="./taps">Recipe packs (taps)</a>) or waiting drafts (<a href="./drafts">Drafts from an assistant</a>); those are checked when a pack is added or updated, when its recipes are loaded, and when a draft is approved. Name a file to check it by hand: <code>ripeat validate path/to/draft.yaml</code>.</p><h2 id="strict-recipes" tabindex="-1">Strict recipes <a class="header-anchor" href="#strict-recipes" aria-label="Permalink to &quot;Strict recipes&quot;">​</a></h2><p>Recipes are read strictly everywhere, not only by <code>validate</code>: an unknown key in a recipe or in one of its platform entries is an error for every command that loads recipes. Fix it, or find it with <code>ripeat validate</code>.</p><h2 id="ripeat-schema-recipe-profile-policy-admin-policy" tabindex="-1"><code>ripeat schema recipe|profile|policy|admin-policy</code> <a class="header-anchor" href="#ripeat-schema-recipe-profile-policy-admin-policy" aria-label="Permalink to &quot;`ripeat schema recipe|profile|policy|admin-policy`&quot;">​</a></h2><p>Prints a JSON Schema for that kind of file, so an editor can complete keys and underline mistakes while you type. It is generated from the same types ripeat reads, so it lists exactly the keys and install methods ripeat knows.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ripeat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> recipe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> recipe.schema.json</span></span></code></pre></div><p>With the YAML extension for VS Code, point a file at it with a first line such as <code># yaml-language-server: $schema=./recipe.schema.json</code>.</p><p>The schema checks structure only. <code>ripeat validate</code> is the authority: it also checks things a schema cannot, such as whether a required recipe exists or whether dependencies loop.</p>',27)])])}const k=a(r,[["render",s]]);export{m as __pageData,k as default};
